# Provenance: 3rd analysis of 2026-11-15 (section 10 of ACHADOS). Read-only. POST HOC.
# Input: res_b3_cascata_motivos.csv (generated by b3_cascade_reasons.py).
import sys

import numpy as np
import pandas as pd

D = pd.read_csv(sys.argv[1])
pd.set_option("display.width", 250)
pd.set_option("display.max_rows", 200)
D["fam"] = D.cenario.str.replace("benchmark_|real_", "", regex=True).str.split("_").str[:2].str.join("_")
D.loc[D.cenario.str.contains("causal_chamber"), "fam"] = "causal_chamber"
D["best_sig"] = D.best_p <= D.best_pmax
D["lin_sig"] = D.lin_p <= D.lin_pmax
print(len(D), "candidates (lag>=1) with log")
C = D[D.fam == "causal_chamber"]
print("\n== Causal Chambers (20 scenarios, all sets): candidates by ground truth")
print(C.groupby("ehv").agg(n=("s6", "size"), s6=("s6", "mean"), melhor_aceita=("best_acc", "mean"),
                           melhor_p_sig=("best_sig", "mean"), linear_aceita=("lin_acc", "mean"), linear_p_sig=("lin_sig", "mean"),
                           varT_linear_med=("lin_varT", "median"), r2T_linear_med=("lin_r2T", "median"),
                           r2O_linear_med=("lin_r2O", "median")).round(3).to_string())
print("   best-fit model:", C.best.value_counts(normalize=True).round(2).to_dict())


def count_reasons(s):
    c = {}
    for x in s.fillna(""):
        for k in set(x.split("|")):
            if k:
                c[k] = c.get(k, 0) + 1
    return pd.Series(c).sort_values(ascending=False)


V = C[C.ehv]
print("\n   TRUE pairs:", len(V), "| linear rejects:", int((~V.lin_acc.astype(bool)).sum()))
print((count_reasons(V.lin_motivos) / len(V)).round(3).to_string())
F = C[~C.ehv]
print("\n   FALSE pairs:", len(F))
print((count_reasons(F.lin_motivos) / len(F)).round(3).to_string())
print("\n== Only the model's p-value (conditional test), per family, development sets:")
print("   precision and recall over the candidates")


def pr(S, col):
    d = S[S[col].astype(bool)]
    return len(d), (d.ehv.mean() if len(d) else np.nan), d.ehv.sum() / max(S.ehv.sum(), 1)


T = []
for fam, S in D[D.conj != "cc9_visto"].groupby("fam"):
    r = {"fam": fam, "cand": len(S), "base_cand": round(S.ehv.mean(), 3)}
    for name, col in [("s6", "s6"), ("lin_p", "lin_sig"), ("melhor_p", "best_sig")]:
        n, p, rv = pr(S, col)
        r.update({name + "_n": n, name + "_prec": round(p, 3), name + "_rev": round(rv, 3)})
    T.append(r)
print(pd.DataFrame(T).to_string(index=False))
